import json
import csv

# Load merchant data
with open('/private/tmp/dabstep-claude-work-1753-ebmw7u5d/context/merchant_data.json') as f:
    merchants = json.load(f)

belles = None
for m in merchants:
    if m['merchant'] == 'Belles_cookbook_store':
        belles = m
        break

# Load fees
with open('/private/tmp/dabstep-claude-work-1753-ebmw7u5d/context/fees.json') as f:
    fees = json.load(f)

# Belles' merchant details
belles_mcc = belles['merchant_category_code']
belles_account_type = belles['account_type']
belles_capture_delay = belles['capture_delay']

# Belles transactions in March 2023 (day 60-90 for 2023)
belles_transactions = []
with open('/private/tmp/dabstep-claude-work-1753-ebmw7u5d/context/payments.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['merchant'] == 'Belles_cookbook_store':
            y = int(row['year'])
            doy = int(row['day_of_year'])
            if y == 2023 and 60 <= doy <= 90:
                belles_transactions.append(row)

total_volume = sum(float(t['eur_amount']) for t in belles_transactions)
fraudulent_volume = sum(float(t['eur_amount']) for t in belles_transactions if t['has_fraudulent_dispute'] == 'True')
fraud_pct = (fraudulent_volume / total_volume) * 100 if total_volume > 0 else 0

print(f"Belles: MCC={belles_mcc}, AccountType={belles_account_type}, CaptureDelay={belles_capture_delay}")
print(f"Volume: {total_volume:.2f}, Fraud%: {fraud_pct:.2f}%")

# Helper functions
def capture_delay_matches(merchant_delay, fee_delay):
    if fee_delay is None:
        return True
    try:
        merchant_days = int(merchant_delay)
    except (ValueError, TypeError):
        merchant_days = None

    if merchant_days is not None:
        if fee_delay == '<3':
            return merchant_days < 3
        elif fee_delay == '>5':
            return merchant_days > 5
        elif fee_delay == '3-5':
            return 3 <= merchant_days <= 5
        elif fee_delay == 'immediate':
            return merchant_days <= 1
        elif fee_delay == 'manual':
            return False
        else:
            # Exact match for numeric delay values
            return str(merchant_days) == fee_delay
    else:
        if fee_delay == merchant_delay:
            return True
        elif fee_delay == '<3' and merchant_delay == 'immediate':
            return True
        elif fee_delay == '<3' and merchant_delay == '1':
            return True
    return False

def fraud_level_matches(merchant_fraud_pct, fee_fraud_level):
    if fee_fraud_level is None:
        return True
    if '>' in fee_fraud_level:
        threshold = float(fee_fraud_level.replace('>', '').replace('%', ''))
        return merchant_fraud_pct > threshold
    elif '<' in fee_fraud_level:
        threshold = float(fee_fraud_level.replace('<', '').replace('%', ''))
        return merchant_fraud_pct < threshold
    elif '-' in fee_fraud_level:
        parts = fee_fraud_level.split('-')
        low = float(parts[0].replace('%', ''))
        high = float(parts[1].replace('%', ''))
        return low <= merchant_fraud_pct <= high
    return False

def volume_matches(merchant_volume, fee_volume):
    if fee_volume is None:
        return True
    vol = merchant_volume
    if fee_volume == '<100k':
        return vol < 100000
    elif fee_volume == '100k-1m':
        return 100000 <= vol <= 1000000
    elif fee_volume == '1m-5m':
        return 1000000 < vol <= 5000000
    elif fee_volume == '>5m':
        return vol > 5000000
    return False

# Now check all fees
matching_fees = set()
for fee in fees:
    # Merchant-level criteria
    # account_type
    if fee['account_type'] and 'R' not in fee['account_type']:
        continue
    # merchant_category_code
    if fee['merchant_category_code'] and belles_mcc not in fee['merchant_category_code']:
        continue
    # capture_delay
    if not capture_delay_matches(belles_capture_delay, fee['capture_delay']):
        continue
    # monthly_volume
    if not volume_matches(total_volume, fee['monthly_volume']):
        continue
    # monthly_fraud_level
    if not fraud_level_matches(fraud_pct, fee['monthly_fraud_level']):
        continue

    # If merchant-level criteria match, check per-transaction criteria
    for txn in belles_transactions:
        # card_scheme
        if fee['card_scheme'] != txn['card_scheme']:
            continue
        # is_credit
        if fee['is_credit'] is not None and fee['is_credit'] != (txn['is_credit'] == 'True'):
            continue
        # aci
        if fee['aci'] and txn['aci'] not in fee['aci']:
            continue
        # intracountry
        txn_intracountry = (txn['acquirer_country'] == txn['issuing_country'])
        if fee['intracountry'] is not None and fee['intracountry'] != txn_intracountry:
            continue

        # All criteria match!
        matching_fees.add(fee['ID'])
        break

print(f"\nApplicable fee IDs: {sorted(matching_fees)}")
print(f"Total: {len(matching_fees)}")

