import json
import csv

# Load merchant data
with open('./context/merchant_data.json') as f:
    merchants = json.load(f)

# Load fees data
with open('./context/fees.json') as f:
    fees = json.load(f)

# Read all payments for Belles on day 10 of 2023
belles_payments = []
with open('./context/payments.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['merchant'] == 'Belles_cookbook_store' and row['day_of_year'] == '10' and row['year'] == '2023':
            belles_payments.append(row)

# Belles characteristics
belles = None
for m in merchants:
    if m['merchant'] == 'Belles_cookbook_store':
        belles = m
        break

capture_delay = belles['capture_delay']  # "1"
mcc = belles['merchant_category_code']    # 5942
account_type = belles['account_type']     # "R"

print(f"Belles: mcc={mcc}, acct={account_type}, capture_delay='{capture_delay}'")
print(f"Payments on day 10: {len(belles_payments)}")

def capture_delay_matches(fee_cd, merchant_cd):
    """Check if merchant's capture_delay falls within fee's capture_delay rule"""
    if fee_cd is None:
        return True
    try:
        merchant_days = int(merchant_cd)
    except ValueError:
        return str(fee_cd) == merchant_cd
    if fee_cd == "immediate":
        return merchant_days == 0
    elif fee_cd == "manual":
        return False
    elif fee_cd == "3-5":
        return 3 <= merchant_days <= 5
    elif fee_cd.startswith(">"):
        return merchant_days > int(fee_cd[1:])
    elif fee_cd.startswith("<"):
        return merchant_days < int(fee_cd[1:])
    else:
        return str(fee_cd) == str(merchant_cd)

def mcc_matches(fee_mcc_list, merchant_mcc):
    if not fee_mcc_list:
        return True
    return merchant_mcc in fee_mcc_list

def account_type_matches(fee_acct_list, merchant_acct):
    if not fee_acct_list:
        return True
    return merchant_acct in fee_acct_list

def is_credit_matches(fee_is_credit, txn_is_credit):
    if fee_is_credit is None:
        return True
    return str(fee_is_credit).lower() == txn_is_credit.lower()

def aci_matches(fee_aci_list, txn_aci):
    if fee_aci_list is None or not fee_aci_list:
        return True
    return txn_aci in fee_aci_list

def intracountry_matches(fee_intracountry, txn_issuing, txn_acquirer):
    if fee_intracountry is None:
        return True
    is_domestic = (txn_issuing == txn_acquirer)
    if fee_intracountry == 1.0:
        return is_domestic
    elif fee_intracountry == 0.0:
        return not is_domestic
    return False

# Filter by merchant-level characteristics
merchant_matching = []
for fee in fees:
    if not mcc_matches(fee['merchant_category_code'], mcc):
        continue
    if not account_type_matches(fee['account_type'], account_type):
        continue
    if not capture_delay_matches(fee['capture_delay'], capture_delay):
        continue
    merchant_matching.append(fee)

print(f"\nMerchant-matching fees: {len(merchant_matching)}")

# For each, check if ANY transaction on day 10 matches remaining criteria
applicable_ids = []
for fee in merchant_matching:
    for payment in belles_payments:
        if fee['card_scheme'] != payment['card_scheme']:
            continue
        if not is_credit_matches(fee['is_credit'], payment['is_credit']):
            continue
        if not aci_matches(fee['aci'], payment['aci']):
            continue
        if not intracountry_matches(fee['intracountry'], payment['issuing_country'], payment['acquirer_country']):
            continue
        applicable_ids.append(fee['ID'])
        break

print(f"\nApplicable fee IDs: {sorted(set(applicable_ids))}")

